     1	import { GatewayError } from "./errors.ts";
     2	
     3	/** `bytes4(keccak256("html()"))`, ERC-8244. */
     4	export const HTML_SELECTOR = "0x33c34ac3";
     5	/** `bytes4(keccak256("request(string[],(string,string)[])"))`, ERC-5219. */
     6	export const REQUEST_SELECTOR = "0x1374c460";
     7	
     8	const WORD = 32;
     9	const MAX_HEADERS = 64;
    10	/**
    11	 * Total bytes of key and value text one response's headers may carry. The count cap alone bounded
    12	 * how many headers were read and not how much they decoded to: every pair's key and value offset is
    13	 * checked against the data's bounds only, so all 128 of them may name one string and a capped
    14	 * response decodes to many times its size (F3, the 2026-11-20 review).
    15	 *
    16	 * Chosen rather than measured, at about four times a long content security policy. The live fixture
    17	 * returns 49 bytes of header text at most, measured on both testnets at this commit.
    18	 */
    19	const MAX_HEADER_BYTES = 16_384;
    20	const utf8 = new TextEncoder();
    21	
    22	/**
    23	 * Validated in the conversion loop rather than by a regular expression. `/^0x([0-9a-fA-F]{2})*$/`
    24	 * backtracks once per byte and threw `RangeError: Maximum call stack size exceeded` above about
    25	 * 4 MiB — inside the response size cap, so a large document failed at every endpoint in turn and was
    26	 * served as a 502 that blamed the endpoints (F4, the 2026-11-20 review). One pass, no recursion, and
    27	 * the first character that is not a hex digit throws `bad-response`.
    28	 */
    29	function notHex(): never {
    30	  throw new GatewayError("bad-response", "result is not hex");
    31	}
    32	
    33	function nibble(code: number): number {
    34	  if (code >= 0x30 && code <= 0x39) return code - 0x30;
    35	  if (code >= 0x61 && code <= 0x66) return code - 0x57;
    36	  if (code >= 0x41 && code <= 0x46) return code - 0x37;
    37	  return -1;
    38	}
    39	
    40	export function hexToBytes(hex: string): Uint8Array {
    41	  if (hex.length < 2 || hex.charCodeAt(0) !== 0x30 || hex.charCodeAt(1) !== 0x78 || hex.length % 2 !== 0) notHex();
    42	  const out = new Uint8Array((hex.length - 2) / 2);
    43	  for (let i = 0; i < out.length; i++) {
    44	    const hi = nibble(hex.charCodeAt(2 + i * 2));
    45	    const lo = nibble(hex.charCodeAt(3 + i * 2));
    46	    if (hi < 0 || lo < 0) notHex();
    47	    out[i] = (hi << 4) | lo;
    48	  }
    49	  return out;
    50	}
    51	
    52	export function bytesToHex(bytes: Uint8Array): string {
    53	  let out = "0x";
    54	  for (const b of bytes) out += b.toString(16).padStart(2, "0");
    55	  return out;
    56	}
    57	
    58	function word(n: number): Uint8Array {
    59	  const out = new Uint8Array(WORD);
    60	  new DataView(out.buffer).setUint32(WORD - 4, n);
    61	  return out;
    62	}
    63	
    64	function concat(parts: Uint8Array[]): Uint8Array {
    65	  const out = new Uint8Array(parts.reduce((n, p) => n + p.length, 0));
    66	  let at = 0;
    67	  for (const p of parts) {
    68	    out.set(p, at);
    69	    at += p.length;
    70	  }
    71	  return out;
    72	}
    73	
    74	function encodeString(s: string): Uint8Array {
    75	  const data = utf8.encode(s);
    76	  const padded = new Uint8Array(Math.ceil(data.length / WORD) * WORD);
    77	  padded.set(data);
    78	  return concat([word(data.length), padded]);
    79	}
    80	
    81	/** A dynamic array of dynamic items: length, one offset per item, then the items. */
    82	function encodeArray(items: Uint8Array[]): Uint8Array {
    83	  const offsets: Uint8Array[] = [];
    84	  let at = items.length * WORD;
    85	  for (const item of items) {
    86	    offsets.push(word(at));
    87	    at += item.length;
    88	  }
    89	  return concat([word(items.length), ...offsets, ...items]);
    90	}
    91	
    92	function encodePair([key, value]: [string, string]): Uint8Array {
    93	  const k = encodeString(key);
    94	  return concat([word(2 * WORD), word(2 * WORD + k.length), k, encodeString(value)]);
    95	}
    96	
    97	/** Calldata for ERC-5219 `request(string[] resource, KeyValue[] params)`. */
    98	export function encodeRequest(resource: string[], params: [string, string][]): string {
    99	  const r = encodeArray(resource.map(encodeString));
   100	  const p = encodeArray(params.map(encodePair));
   101	  return REQUEST_SELECTOR + bytesToHex(concat([word(2 * WORD), word(2 * WORD + r.length), r, p])).slice(2);
   102	}
   103	
   104	/**
   105	 * Reads ABI words out of bytes a contract chose. Every offset and length is attacker-controlled,
   106	 * so each read is bounds-checked against the buffer and nothing is allocated from a claimed size.
   107	 */
   108	function uint(data: Uint8Array, at: number): number {
   109	  if (!Number.isSafeInteger(at) || at < 0 || at + WORD > data.length) {
   110	    throw new GatewayError("bad-response", "return data is truncated");
   111	  }
   112	  for (let i = at; i < at + WORD - 6; i++) {
   113	    if (data[i] !== 0) throw new GatewayError("bad-response", "return data has an out-of-range word");
   114	  }
   115	  let n = 0;
   116	  for (let i = at + WORD - 6; i < at + WORD; i++) n = n * 256 + (data[i] ?? 0);
   117	  return n;
   118	}
   119	
   120	function bytesAt(data: Uint8Array, at: number): Uint8Array {
   121	  const length = uint(data, at);
   122	  const start = at + WORD;
   123	  if (start + length > data.length) throw new GatewayError("bad-response", "return data is truncated");
   124	  return data.subarray(start, start + length);
   125	}
   126	
   127	/** Return data of `html()`: one ABI `string`, handed back as its raw bytes. */
   128	export function decodeString(data: Uint8Array): Uint8Array {
   129	  return bytesAt(data, uint(data, 0));
   130	}
   131	
   132	export interface RequestResult {
   133	  status: number;
   134	  body: Uint8Array;
   135	  headers: [string, string][];
   136	}
   137	
   138	/** Return data of ERC-5219 `request()`: `(uint16 statusCode, string body, KeyValue[] headers)`. */
   139	export function decodeRequestResult(data: Uint8Array): RequestResult {
   140	  const status = uint(data, 0);
   141	  const body = bytesAt(data, uint(data, WORD));
   142	  const list = uint(data, 2 * WORD);
   143	  const count = uint(data, list);
   144	  if (count > MAX_HEADERS) throw new GatewayError("bad-response", "too many headers");
   145	  const base = list + WORD;
   146	  const text = new TextDecoder("utf-8", { fatal: true });
   147	  const headers: [string, string][] = [];
   148	  let headerBytes = 0;
   149	  try {
   150	    for (let i = 0; i < count; i++) {
   151	      const pair = base + uint(data, base + i * WORD);
   152	      const key = bytesAt(data, pair + uint(data, pair));
   153	      const value = bytesAt(data, pair + uint(data, pair + WORD));
   154	      /* Summed and checked before either is decoded: decoding is where the bytes are copied, so a
   155	         bound applied afterwards would already have paid for the allocation it exists to refuse. */
   156	      headerBytes += key.length + value.length;
   157	      if (headerBytes > MAX_HEADER_BYTES) {
   158	        throw new GatewayError("bad-response", `header text exceeds ${MAX_HEADER_BYTES} bytes`);
   159	      }
   160	      headers.push([text.decode(key), text.decode(value)]);
   161	    }
   162	  } catch (e) {
   163	    if (e instanceof GatewayError) throw e;
   164	    throw new GatewayError("bad-response", "header is not UTF-8");
   165	  }
   166	  return { status, body, headers };
   167	}
