     1	import { HTML_SELECTOR, decodeRequestResult, decodeString, encodeRequest } from "./abi.ts";
     2	import { GatewayError } from "./errors.ts";
     3	import { type GatewayResponse, type Rpc, RpcRevert } from "./ports.ts";
     4	import type { Frame, Target } from "./target.ts";
     5	
     6	/**
     7	 * Headers a contract may set on its own response. An allowlist, because the same core runs behind
     8	 * adapters where a contract-chosen `Set-Cookie` or `Clear-Site-Data` would reach past its origin.
     9	 */
    10	const PASSED_HEADERS = new Set([
    11	  "content-type",
    12	  "content-language",
    13	  "content-disposition",
    14	  "content-security-policy",
    15	  "referrer-policy",
    16	  "permissions-policy",
    17	  "cross-origin-opener-policy",
    18	  "cross-origin-embedder-policy",
    19	  "cross-origin-resource-policy",
    20	  "access-control-allow-origin",
    21	  "x-frame-options",
    22	]);
    23	
    24	/** Never cached below the client, and never sniffed into a type the contract did not declare. */
    25	const FIXED_HEADERS: [string, string][] = [
    26	  ["cache-control", "no-store"],
    27	  ["x-content-type-options", "nosniff"],
    28	];
    29	
    30	const HEADER_VALUE = /^[\t\x20-\x7e]*$/;
    31	
    32	/**
    33	 * The framing rule a root document is served with unless the build says `"any"` (#57).
    34	 *
    35	 * `html()` returns bytes and no headers, so a root document had no framing rule at all and any site
    36	 * could put a contract's page in a frame and read the visitor's clicks against it. The gateway
    37	 * supplies the rule the document cannot: same-origin framing only, which for a gateway origin means
    38	 * the contract's own pages.
    39	 */
    40	export const ROOT_FRAME_POLICY = "frame-ancestors 'self'";
    41	
    42	function respond(status: number, type: string, body: Uint8Array, extra: [string, string][] = []): GatewayResponse {
    43	  return { status, headers: [["content-type", type], ...extra, ...FIXED_HEADERS], body };
    44	}
    45	
    46	/** Plain text, always: an error body never carries markup built from a URL or a contract. */
    47	export function errorResponse(error: unknown): GatewayResponse {
    48	  const known = error instanceof GatewayError ? error : new GatewayError("upstream", "internal gateway error");
    49	  const body = new TextEncoder().encode(`gw44: ${known.message}\n`);
    50	  return respond(known.status, "text/plain; charset=utf-8", body);
    51	}
    52	
    53	/** An address with no code, or a fallback that returns nothing, answers a call with zero bytes. */
    54	async function call(target: Target, rpc: Rpc, data: string): Promise<Uint8Array> {
    55	  const out = await rpc.call(target.chain, target.address, data);
    56	  if (out.length === 0) throw new GatewayError("not-found", "the address does not serve this resource");
    57	  return out;
    58	}
    59	
    60	async function html(target: Target, rpc: Rpc, frame: Frame): Promise<GatewayResponse> {
    61	  const body = decodeString(await call(target, rpc, HTML_SELECTOR));
    62	  if (body.length === 0) throw new GatewayError("not-found", "html() returned an empty document");
    63	  const framing: [string, string][] = frame === "any" ? [] : [["content-security-policy", ROOT_FRAME_POLICY]];
    64	  return respond(200, "text/html; charset=utf-8", body, framing);
    65	}
    66	
    67	async function request(target: Target, rpc: Rpc): Promise<GatewayResponse> {
    68	  const data = await call(target, rpc, encodeRequest(target.resource, target.params));
    69	  const result = decodeRequestResult(data);
    70	  // The range a `Response` can be built with; 1xx and 3xx-without-Location are not documents.
    71	  if (result.status < 200 || result.status > 599) {
    72	    throw new GatewayError("bad-response", `contract returned status ${result.status}`);
    73	  }
    74	  let type = "application/octet-stream";
    75	  const extra: [string, string][] = [];
    76	  for (const [rawKey, value] of result.headers) {
    77	    const key = rawKey.toLowerCase();
    78	    // A synthesized response is not content-decoded by the browser; garbage is worse than a 502.
    79	    if (key === "content-encoding" && value.toLowerCase() !== "identity") {
    80	      throw new GatewayError("bad-response", `content-encoding ${value} is not supported`);
    81	    }
    82	    if (!PASSED_HEADERS.has(key) || !HEADER_VALUE.test(value)) continue;
    83	    if (key === "content-type") type = value;
    84	    else extra.push([key, value]);
    85	  }
    86	  const nullBody = result.status === 204 || result.status === 205 || result.status === 304;
    87	  return respond(result.status, type, nullBody ? new Uint8Array() : result.body, extra);
    88	}
    89	
    90	/**
    91	 * The whole gateway: the root is ERC-8244 `html()`, every other path is ERC-5219 `request()`.
    92	 * Never throws; a failure is a response.
    93	 *
    94	 * `frame` is the build's framing setting and applies to a root document only: a sub-path's headers
    95	 * are the contract's, within `PASSED_HEADERS`, and a contract that wants a policy there sets one.
    96	 */
    97	export async function resolve(target: Target, rpc: Rpc, frame: Frame = "self"): Promise<GatewayResponse> {
    98	  try {
    99	    if (!rpc.supports(target.chain)) {
   100	      throw new GatewayError("unknown-chain", `chain ${target.chain} is not configured on this gateway`);
   101	    }
   102	    return await (target.resource.length === 0 ? html(target, rpc, frame) : request(target, rpc));
   103	  } catch (error) {
   104	    if (error instanceof RpcRevert) {
   105	      return errorResponse(new GatewayError("not-found", "the contract does not serve this resource"));
   106	    }
   107	    return errorResponse(error);
   108	  }
   109	}
