     1	import { GatewayError } from "./errors.ts";
     2	
     3	export interface Target {
     4	  /** Decimal chain id, no leading zeros. */
     5	  chain: string;
     6	  /** Lower-case, 0x-prefixed, 20 bytes. */
     7	  address: string;
     8	  /** Percent-decoded path segments. Empty for the root. */
     9	  resource: string[];
    10	  params: [string, string][];
    11	  /**
    12	   * Set when a path-form URL lacks the slash after the address. Relative URLs in the document
    13	   * would resolve one level too high, so the adapter redirects here instead of serving.
    14	   */
    15	  redirect?: string;
    16	  /** How to answer `redirect`; 308 when absent. 302 is for a redirect whose destination can change. */
    17	  redirectStatus?: 302 | 308;
    18	}
    19	
    20	/**
    21	 * One project's contracts, one per chain, as `gw44.json` names them. Several chains of one project
    22	 * share one origin and are told apart by the first path segment, which is a path and not a browser
    23	 * boundary: they share storage, the worker registration and any wallet permission the visitor has
    24	 * granted, so each is only as safe as the weakest contract configured beside it. An application
    25	 * that keeps per-chain state separates it by chain itself; nothing in the origin does that for it.
    26	 * What the prefix buys is that a document's absolute URL fails instead of reading another chain's
    27	 * contract, and that one project's contracts stay out of every other project's origin (decision 9;
    28	 * F1 of the 2026-11-20 review, which found this comment claiming the opposite).
    29	 */
    30	export interface Pins {
    31	  /** A key of `contracts`; the chain `/` goes to. */
    32	  default: string;
    33	  /** Chain id to lower-case address. At least one. */
    34	  contracts: Record<string, string>;
    35	  /** Who may frame a root document; `"self"` when absent. See `Frame`. */
    36	  frame?: Frame;
    37	}
    38	
    39	/**
    40	 * Who may frame a contract's root document. `"self"` — the default, and what a `PIN=` build takes —
    41	 * serves it with `content-security-policy: frame-ancestors 'self'`; `"any"` omits the header and
    42	 * lets any site frame it. The whole setting is those two words: a project that needs a policy of its
    43	 * own serves its page from `request()`, where it sets its own headers (#57).
    44	 */
    45	export type Frame = "self" | "any";
    46	
    47	const ADDRESS = /^0x[0-9a-f]{40}$/;
    48	const CHAIN = /^[1-9][0-9]{0,15}$/;
    49	
    50	/** A decimal chain id: no leading zeros, no sign, no separators. The URL form's rule, exported so
    51	 *  the chains file is checked against the same one rather than a second copy of it. */
    52	export function isChainId(value: string): boolean {
    53	  return CHAIN.test(value);
    54	}
    55	
    56	/** Loopback only: `localhost`, any `*.localhost`, 127.0.0.0/8 and `[::1]`. */
    57	export function isLoopback(hostname: string): boolean {
    58	  return (
    59	    hostname === "localhost" ||
    60	    hostname.endsWith(".localhost") ||
    61	    hostname === "[::1]" ||
    62	    /^127(\.[0-9]{1,3}){3}$/.test(hostname)
    63	  );
    64	}
    65	
    66	function segments(pathname: string): string[] {
    67	  const parts = pathname.split("/").slice(1);
    68	  try {
    69	    return parts.map((p) => decodeURIComponent(p));
    70	  } catch {
    71	    throw new GatewayError("bad-target", "malformed percent-encoding in path");
    72	  }
    73	}
    74	
    75	/**
    76	 * Two URL forms, and nothing else:
    77	 *
    78	 *   host form  `<address>.<chain>.<any base>/<path>`   every contract its own origin
    79	 *   path form  `<loopback>/<chain>/<address>/<path>`   every contract on one origin
    80	 *
    81	 * The path form is honoured on loopback hosts only. On a public host it would put every contract
    82	 * in one origin, where any document could read another's storage or replace its service worker.
    83	 *
    84	 * Returns null when the URL names no contract, so the adapter can leave it to the static host.
    85	 */
    86	export function parseTarget(url: URL): Target | null {
    87	  const labels = url.hostname.toLowerCase().split(".");
    88	  const params: [string, string][] = [...url.searchParams.entries()];
    89	
    90	  const [first, second] = labels;
    91	  if (labels.length >= 3 && first !== undefined && second !== undefined && ADDRESS.test(first)) {
    92	    if (!CHAIN.test(second)) return null;
    93	    const resource = segments(url.pathname);
    94	    return { chain: second, address: first, resource: trimRoot(resource), params };
    95	  }
    96	
    97	  if (!isLoopback(url.hostname.toLowerCase())) return null;
    98	  const [chain, rawAddress, ...rest] = segments(url.pathname);
    99	  const address = rawAddress?.toLowerCase();
   100	  if (chain === undefined || address === undefined) return null;
   101	  if (!CHAIN.test(chain) || !ADDRESS.test(address)) return null;
   102	  const target: Target = { chain, address, resource: trimRoot(rest), params };
   103	  if (rest.length === 0) target.redirect = `${url.pathname}/${url.search}`;
   104	  return target;
   105	}
   106	
   107	/**
   108	 * `<chain>:<address>`, the pin as a build gives it. Throws rather than returning null: a URL that
   109	 * names no contract is ordinary and a malformed pin is a mistake, so the two must not look alike.
   110	 */
   111	export function parsePin(text: string): Pins {
   112	  const parts = text.split(":");
   113	  const [chain, rawAddress] = parts;
   114	  if (parts.length !== 2 || chain === undefined || rawAddress === undefined) {
   115	    throw new GatewayError("bad-target", `pin must be <chain>:<address>; got ${JSON.stringify(text)}`);
   116	  }
   117	  const address = rawAddress.toLowerCase();
   118	  if (!CHAIN.test(chain)) {
   119	    throw new GatewayError("bad-target", `pin chain must be a decimal chain id; got ${JSON.stringify(chain)}`);
   120	  }
   121	  if (!ADDRESS.test(address)) {
   122	    throw new GatewayError("bad-target", `pin address must be 0x and 40 hex digits; got ${JSON.stringify(rawAddress)}`);
   123	  }
   124	  return { default: chain, contracts: { [chain]: address } };
   125	}
   126	
   127	/**
   128	 * The configuration file, validated. Throws rather than returning null for the same reason
   129	 * `parsePin` does: a malformed configuration is a mistake, not a URL that names no contract.
   130	 */
   131	export function parsePins(value: unknown): Pins {
   132	  if (typeof value !== "object" || value === null || Array.isArray(value)) {
   133	    throw new GatewayError("bad-target", `configuration must be a JSON object; got ${describe(value)}`);
   134	  }
   135	  const record = value as Record<string, unknown>;
   136	  for (const key of Object.keys(record)) {
   137	    if (key !== "default" && key !== "contracts" && key !== "frame") {
   138	      throw new GatewayError("bad-target", `configuration has no key ${JSON.stringify(key)}`);
   139	    }
   140	  }
   141	  const frame = record["frame"];
   142	  if (frame !== undefined && frame !== "self" && frame !== "any") {
   143	    throw new GatewayError("bad-target", `configuration "frame" must be "self" or "any"; got ${describe(frame)}`);
   144	  }
   145	  const raw = record["contracts"];
   146	  if (typeof raw !== "object" || raw === null || Array.isArray(raw)) {
   147	    throw new GatewayError("bad-target", `configuration "contracts" must be an object; got ${describe(raw)}`);
   148	  }
   149	  const contracts: Record<string, string> = {};
   150	  for (const [chain, address] of Object.entries(raw as Record<string, unknown>)) {
   151	    if (!CHAIN.test(chain)) {
   152	      throw new GatewayError("bad-target", `configuration chain ${JSON.stringify(chain)} is not a decimal chain id`);
   153	    }
   154	    if (typeof address !== "string" || !ADDRESS.test(address.toLowerCase())) {
   155	      throw new GatewayError(
   156	        "bad-target",
   157	        `configuration address for chain ${chain} must be 0x and 40 hex digits; got ${describe(address)}`,
