     2	import { GatewayError } from "../../core/errors.ts";
     3	import { type Rpc, RpcRevert } from "../../core/ports.ts";
     4	
     5	/** Chain id to its JSON-RPC endpoints, tried in order. */
     6	export type Chains = Readonly<Record<string, readonly string[]>>;
     7	
     8	export interface FetchRpcOptions {
     9	  timeoutMs?: number;
    10	  /** Cap on one JSON-RPC response body. The document arrives hex-encoded, so twice its size. */
    11	  maxBytes?: number;
    12	  fetch?: typeof fetch;
    13	}
    14	
    15	interface JsonRpcReply {
    16	  result?: unknown;
    17	  error?: { code?: unknown; message?: unknown; data?: unknown };
    18	}
    19	
    20	async function readCapped(res: Response, maxBytes: number): Promise<string> {
    21	  if (!res.body) return "";
    22	  const reader = res.body.getReader();
    23	  const text = new TextDecoder();
    24	  let out = "";
    25	  let seen = 0;
    26	  for (;;) {
    27	    const { done, value } = await reader.read();
    28	    if (done) return out + text.decode();
    29	    seen += value.length;
    30	    if (seen > maxBytes) {
    31	      await reader.cancel();
    32	      throw new Error("response exceeds the size cap");
    33	    }
    34	    out += text.decode(value, { stream: true });
    35	  }
    36	}
    37	
    38	/** A revert is the contract's answer; every other JSON-RPC error is the endpoint's problem. */
    39	function isRevert(error: NonNullable<JsonRpcReply["error"]>): boolean {
    40	  return error.code === 3 || (typeof error.message === "string" && /revert/i.test(error.message));
    41	}
    42	
    43	/**
    44	 * JSON-RPC over `fetch`, with ordered failover. Limits: one endpoint's word is taken as the chain's;
    45	 * there is no quorum and no proof verification.
    46	 *
    47	 * `timeoutMs` bounds **one** endpoint, not the call. The endpoints are tried in order and nothing
    48	 * spans the list, so with `n` endpoints a single `call` can take up to `n × timeoutMs` before it
    49	 * throws `upstream` — at the defaults, two endpoints that never answer cost 20 s. Callers that need
    50	 * a deadline across the whole list must impose it themselves; a budget here is M04's, not this
    51	 * adapter's.
    52	 */
    53	export function createFetchRpc(chains: Chains, options: FetchRpcOptions = {}): Rpc {
    54	  const { timeoutMs = 10_000, maxBytes = 16 * 1024 * 1024 } = options;
    55	  const send = options.fetch ?? fetch;
    56	
    57	  async function callOne(endpoint: string, to: string, data: string): Promise<Uint8Array> {
    58	    const res = await send(endpoint, {
    59	      method: "POST",
    60	      headers: { "content-type": "application/json" },
    61	      body: JSON.stringify({ jsonrpc: "2.0", id: 1, method: "eth_call", params: [{ to, data }, "latest"] }),
    62	      signal: AbortSignal.timeout(timeoutMs),
    63	      credentials: "omit",
    64	      cache: "no-store",
    65	      referrerPolicy: "no-referrer",
    66	    });
    67	    /* A non-2xx body is not an answer, whatever it contains. Without this, a 429 or a 500 whose
    68	       body happened to be JSON-RPC-shaped would be believed and failover would not happen. */
    69	    if (!res.ok) throw new Error(`endpoint returned HTTP ${res.status}`);
    70	    const text = await readCapped(res, maxBytes);
    71	    const reply = JSON.parse(text) as JsonRpcReply;
    72	    if (reply.error) {
    73	      if (isRevert(reply.error)) throw new RpcRevert();
    74	      throw new Error("endpoint returned an error");
    75	    }
    76	    if (typeof reply.result !== "string") throw new Error("endpoint returned no result");
    77	    return hexToBytes(reply.result);
    78	  }
    79	
    80	  return {
    81	    supports: (chain) => (chains[chain]?.length ?? 0) > 0,
    82	    async call(chain, to, data) {
    83	      const endpoints = chains[chain] ?? [];
    84	      if (endpoints.length === 0) throw new GatewayError("unknown-chain", `chain ${chain} is not configured`);
    85	      for (const endpoint of endpoints) {
    86	        try {
    87	          return await callOne(endpoint, to, data);
    88	        } catch (error) {
    89	          if (error instanceof RpcRevert) throw error;
    90	          // Deliberately swallowed: the next endpoint is the handling.
    91	        }
    92	      }
    93	      throw new GatewayError("upstream", `no RPC endpoint for chain ${chain} answered`);
    94	    },
    95	  };
    96	}
